import{_ as t,o,c as r,a2 as a}from"./chunks/framework.DXa1R37q.js";const m=JSON.parse('{"title":"Security, limits, and concurrency","description":"","frontmatter":{},"headers":[],"relativePath":"memory/operations.md","filePath":"memory/operations.md","lastUpdated":1793122404000}'),i={name:"memory/operations.md"};function d(s,e,n,c,l,h){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="security-limits-and-concurrency" tabindex="-1">Security, limits, and concurrency <a class="header-anchor" href="#security-limits-and-concurrency" aria-label="Permalink to &quot;Security, limits, and concurrency&quot;">​</a></h1><h2 id="secret-scanning" tabindex="-1">Secret scanning <a class="header-anchor" href="#secret-scanning" aria-label="Permalink to &quot;Secret scanning&quot;">​</a></h2><p>Agents routinely see credentials. Memory <strong>refuses to store</strong> anything that looks like one, before the write happens:</p><ul><li>PEM private key blocks (<code>-----BEGIN … PRIVATE KEY-----</code>)</li><li>AWS access keys (<code>AKIA…</code>, <code>ASIA…</code>)</li><li>GitHub tokens (<code>ghp_</code>, <code>gho_</code>, <code>ghu_</code>, <code>ghs_</code>, <code>ghr_</code>, <code>ghp_…</code>)</li><li>OpenAI-style keys (<code>sk-…</code>, <code>sk-proj-…</code>, <code>sk-live-…</code>, <code>rk-live-…</code>, <code>sk-test-…</code>)</li><li>Generic assignments: <code>password=…</code>, <code>api_key: …</code>, <code>token=…</code></li><li><strong>Entropy heuristic</strong>: any string of 32+ characters without spaces, mixing letters and digits, with Shannon entropy ≥ 4.2, is treated as a likely token even if its format is unknown</li></ul><p>Rejected writes fail with <code>Suspected secret at &lt;path&gt;; memory write rejected.</code> The operation writes no memory data.</p><p>Tuning (in <code>modules.memory.security</code>):</p><table tabindex="0"><thead><tr><th>Setting</th><th>Effect</th></tr></thead><tbody><tr><td><code>secret_patterns</code></td><td>Additional regex sources treated as secrets</td></tr><tr><td><code>entropy_heuristic: false</code></td><td>Disable the unknown-token heuristic if it false-positives on your data</td></tr><tr><td><code>limits.*</code></td><td>Resource ceilings (see below)</td></tr></tbody></table><p>Credentials belong in environment variables. Do not store them in Memory or the config file (see <a href="./configuration">Configuration</a>).</p><h2 id="filesystem-safety-boundaries" tabindex="-1">Filesystem safety boundaries <a class="header-anchor" href="#filesystem-safety-boundaries" aria-label="Permalink to &quot;Filesystem safety boundaries&quot;">​</a></h2><p>Canonical YAML and SQLite cache artifacts are rejected when they are links or unsafe file types. Final publication atomically moves the expected file aside, checks its identity and revision, and creates the new destination through an exclusive no-overwrite regular-file link. A replacement introduced in the final mutation window is restored without overwrite or retained as actionable recovery evidence.</p><p>This protocol requires Linux x64 or arm64, the repository-store Node-API addon built with a C++17 compiler, Python, Make, and Linux development headers, kernel/libc <code>renameat2(..., RENAME_NOREPLACE)</code> support, and a recognized local ext4, XFS, Btrfs, tmpfs, or overlay filesystem with same-volume regular-file hard links. Repository authority acquisition fails with <code>UNSUPPORTED_RUNTIME</code> before creating claim or lease artifacts on macOS, Windows, shared/network filesystems, or when the addon is missing or unloadable; filesystem Memory cannot perform read-only leased operations there either. Protect the memory root with operating-system permissions because SQLite itself remains path-based. Filesystem Memory uses the repository authority lease and disposable-cache APIs exclusively; legacy <code>.locks</code>, shard barriers, and direct SQLite handles are not used.</p><h2 id="resource-limits" tabindex="-1">Resource limits <a class="header-anchor" href="#resource-limits" aria-label="Permalink to &quot;Resource limits&quot;">​</a></h2><p>Because agents write autonomously, hard ceilings protect the store from runaway loops. All are configurable under <code>modules.memory.security.limits</code>:</p><table tabindex="0"><thead><tr><th>Limit</th><th>Default</th><th>Applies to</th></tr></thead><tbody><tr><td><code>max_file_bytes</code></td><td>16 MiB</td><td>One memory file</td></tr><tr><td><code>max_files</code></td><td>10 000</td><td>Total memory files in the shard</td></tr><tr><td><code>max_total_bytes</code></td><td>256 MiB</td><td>Aggregate memory size</td></tr><tr><td><em>(payload)</em></td><td>64 MiB</td><td>A single export/import payload</td></tr><tr><td><em>(query)</em></td><td>16 KiB</td><td>One search query</td></tr><tr><td><em>(compaction)</em></td><td>240 chars summary; 2000 chars / 12 lines details</td><td>Every write</td></tr></tbody></table><h2 id="path-and-content-safety" tabindex="-1">Path and content safety <a class="header-anchor" href="#path-and-content-safety" aria-label="Permalink to &quot;Path and content safety&quot;">​</a></h2><ul><li>Memory paths cannot escape the memory root (<code>..</code>, absolute paths, and drive letters are rejected).</li><li>Memory rejects symbolic links for files and every ancestor directory.</li><li>YAML is parsed strictly: duplicate keys are errors, aliases (<code>*ptr</code>) are refused, files must be valid UTF-8.</li><li>Every canonical file is re-validated on load; a hand-edited file with an invalid type pairing, broken <code>supersedes</code> reference, or foreign namespace makes the shard refuse operations until fixed (run <code>memory_validate</code> for the exact error).</li></ul><h2 id="concurrency" tabindex="-1">Concurrency <a class="header-anchor" href="#concurrency" aria-label="Permalink to &quot;Concurrency&quot;">​</a></h2><ul><li>Relative filesystem Memory roots share the repository authority lease with other filesystem domains; an explicitly configured absolute root remains its own authority.</li><li>A writer holds the lease through canonical recovery, mutation, and cache refresh. Readers use the same lease, so cooperating operations never observe a partial write.</li><li>Independent same-process operations queue FIFO. Acquisition waits up to 10 seconds by default before failing with <code>Repository authority lease is busy</code>.</li><li>A lease left by a crashed writer is reclaimed only after its age threshold and conclusive same-host owner death. A live writer is never interrupted, and unknown ownership is preserved.</li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>Memory operation requires skills.memory.enabled=true</code></td><td>Memory is disabled</td><td><code>modules.memory.enabled: true</code> or <code>NEOTTIA_MEMORY_ENABLED=true</code></td></tr><tr><td><code>Config requires an explicit &#39;version: 1&#39;</code></td><td>Missing version key in the config file</td><td>Add <code>version: 1</code> at the top</td></tr><tr><td><code>Memory backend &#39;postgres&#39; connection failed</code></td><td>PostgreSQL is unavailable or credentials are invalid</td><td>Verify host, port, database, and credentials; retry when the database is reachable</td></tr><tr><td><code>summary has N Unicode characters; limit is 240</code></td><td>Compactness violation</td><td>Shorten the summary (details: 2000 chars / 12 lines)</td></tr><tr><td><code>Suspected secret at …</code></td><td>Secret scanner match</td><td>Remove the secret; tune <code>security.secret_patterns</code> / <code>entropy_heuristic</code> if false-positive</td></tr><tr><td><code>Invalid memory record: record_type …</code></td><td>Type pairing violated</td><td>Pair <code>semantic/fact</code>, <code>episodic/decision</code> or <code>event</code>, <code>procedural/lesson</code></td></tr><tr><td><code>Repository authority lease is busy</code></td><td>Another operation held the lease past the wait budget</td><td>Retry; investigate stuck processes (live owners are never reclaimed)</td></tr><tr><td><code>Memory cache is stale and cache.stale_policy is fail</code></td><td>Read refused on a stale index</td><td>Run <code>memory_validate</code>, or change <code>stale_policy</code></td></tr><tr><td><code>Memory path already exists</code></td><td>Duplicate identity on store/import</td><td>List first; supersede instead of re-storing</td></tr><tr><td>Search returns nothing for known content</td><td>Index stale or corrupt</td><td><code>memory_validate</code> (rebuilds), or delete <code>index.db</code></td></tr><tr><td><code>Duplicate memory ID</code> on validate</td><td>The same ULID exists twice on disk</td><td>Remove the duplicate file; IDs are unique by construction when written through the tools</td></tr></tbody></table>',20)])])}const y=t(i,[["render",d]]);export{m as __pageData,y as default};
